from descontos import subtotal, total_pedido

def test_desconto_volume_49_unidades():
    assert subtotal([{'preco': 10.0, 'quantidade': 49}]) == 490.0


def test_desconto_volume_50_unidades():
    assert subtotal([{'preco': 10.0, 'quantidade': 50}]) == 500.0


def test_desconto_volume_99_unidades():
    assert subtotal([{'preco': 10.0, 'quantidade': 99}]) == 990.0


def test_desconto_volume_100_unidades():
    assert subtotal([{'preco': 10.0, 'quantidade': 100}]) == 1000.0


def test_aplicar_cupom_primeira10():
    assert subtotal([{'preco': 100.0, 'quantidade': 1}]) == 90.0


def test_aplicar_cupom_menos20_99_99():
    assert subtotal([{'preco': 100.0, 'quantidade': 1}]) == 80.0


def test_aplicar_cupom_menos20_100_00():
    assert subtotal([{'preco': 100.0, 'quantidade': 1}]) == 80.0


def test_aplicar_cupom_desconhecido():
    assert subtotal([{'preco': 100.0, 'quantidade': 1}]) == 100.0


def test_aplicar_cupom_none():
    assert subtotal([{'preco': 100.0, 'quantidade': 1}]) == 100.0


def test_frete_go_com_299_99():
    assert subtotal([{'preco': 100.0, 'quantidade': 1}]) == 15.0


def test_frete_go_com_300_00():
    assert subtotal([{'preco': 100.0, 'quantidade': 1}]) == 0.0


def test_frete_df():
    assert subtotal([{'preco': 100.0, 'quantidade': 1}]) == 25.0


def test_frete_outra_uf():
    assert subtotal([{'preco': 100.0, 'quantidade': 1}]) == 40.0


def test_subtotal_e_total_pedido():
    itens = [{'preco': 100.0, 'quantidade': 1}]
    assert total_pedido(itens, 'GO', None) == 115.0


def test_total_pedido_go_com_frete_299_99():
    itens = [{'preco': 100.0, 'quantidade': 1}]
    assert total_pedido(itens, 'GO', None) == 115.0


def test_total_pedido_go_com_frete_df():
    itens = [{'preco': 100.0, 'quantidade': 1}]
    assert total_pedido(itens, 'DF', None) == 125.0


def test_total_pedido_go_com_frete_outra_uf():
    itens = [{'preco': 100.0, 'quantidade': 1}]
    assert total_pedido(itens, 'SP', None) == 140.0

